int main(void)
{
    int a[100], n, i, j, tmp;
    int best;

    if (scanf("%d", &n) != 1 || n < 1 || n > 100)
        return 0;
    for (i = 0; i < n; i++) {
        if (scanf("%d", &a[i]) != 1)
            return 0;
    }

    for (i = 0; i < n - 1; i++) {
        for (j = 0; j < n - 1 - i; j++) {
            if (a[j] > a[j + 1]) {
                tmp = a[j];
                a[j] = a[j + 1];
                a[j + 1] = tmp;
            }
        }
    }

    for (i = 0; i < n; i++) {
        if (i > 0)
            printf(" ");
        printf("%d", a[i]);
    }
    printf("\n");

    if (n < 2) {
        printf("0\n");
        return 0;
    }

    best = a[1] - a[0];
    for (i = 2; i < n; i++) {
        if (a[i] - a[i - 1] < best)
            best = a[i] - a[i - 1];
    }
    printf("%d\n", best);
    return 0;
}

