#include <ctype.h>

int main(void)
{
    char line[2000];
    char buf[2000];
    int len = 0, i, j, ok = 1;

    if (fgets(line, sizeof line, stdin) == NULL)
        return 0;

    for (i = 0; line[i] != '\0'; i++) {
        unsigned char c = (unsigned char)line[i];
        if (isalnum(c))
            buf[len++] = (char)tolower(c);
    }

    for (i = 0, j = len - 1; i < j; i++, j--) {
        if (buf[i] != buf[j]) {
            ok = 0;
            break;
        }
    }
    printf(ok ? "YES\n" : "NO\n");
    return 0;
}

